export type ApiResponseDtoListMissionResponseDto = {
    developCode: number;
    message: string;
    data: Array<MissionResponseDto>;
};

/**
 * 이벤트(EVENT) — 격자 집합을 감싸는 경계 사각형
 */
export type BoxShape = MissionShape & {
    polygon: Array<LatLng>;
};

/**
 * 격자 중심점
 */
export type Cell = {
    gridId: string;
    lat: number;
    lon: number;
};

/**
 * 테마·지속(THEME·CONTINUOUS) — 각 격자 중심점
 */
export type CellsShape = MissionShape & {
    cells: Array<Cell>;
};

/**
 * 좌표 한 점
 */
export type LatLng = {
    lat: number;
    lon: number;
};

/**
 * 활성 미션 하나 — 공통 필드 + 유형별 렌더 shape
 */
export type MissionResponseDto = {
    /**
     * 미션 id (missions.id)
     */
    missionId: number;
    /**
     * 미션 유형 — FE 렌더러 판별자
     */
    type: 'COURSE' | 'AREA' | 'EVENT' | 'THEME' | 'CONTINUOUS' | 'POPUP';
    /**
     * 미션 제목
     */
    title: string;
    /**
     * 완료에 필요한 distinct 방문 격자 수(표시·판정 힌트, 판정은 MSG-223)
     */
    targetCount: number;
    /**
     * 시작 시각. NULL = 무기간(상시)
     */
    startAt: string | null;
    /**
     * 종료 시각. NULL = 무기간(상시)
     */
    endAt: string | null;
    /**
     * 유형별 렌더 shape 하나(type 에 대응하는 PATH/BOX/CELLS/REGION)
     */
    shape: BoxShape | CellsShape | PathShape | RegionShape;
};

/**
 * 미션 유형별 렌더 shape (상위 type 으로 판별). PATH·BOX·CELLS·REGION 중 하나.
 */
export type MissionShape = unknown;

/**
 * 코스(COURSE) — GeoJSON LineString + seq순 포토스팟 마커
 */
export type PathShape = MissionShape & {
    /**
     * 코스 라인 GeoJSON LineString 원문 — missions.path 는 NULL 허용 컬럼이라 없을 수 있다
     */
    line: string | null;
    spots: Array<Spot>;
};

/**
 * 구역(AREA) — region_code 만(경계는 region API 로 별도 조회)
 */
export type RegionShape = MissionShape & {
    /**
     * 행정동 코드 — missions.region_code 는 NULL 허용 컬럼이라 없을 수 있다
     */
    regionCode: string | null;
};

/**
 * 코스 포토스팟 마커
 */
export type Spot = {
    gridId: string;
    lat: number;
    lon: number;
    /**
     * 코스 내 순번 — mission_grids.seq 는 NULL 허용 컬럼이라 없을 수 있다
     */
    seq: number | null;
};

